function updateThemeControls(){const dark=activeTheme()==='dark';document.querySelectorAll('[data-action="toggle-theme"]').forEach(b=>{b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-pressed',String(dark));b.setAttribute('aria-label',dark?'Включить светлую тему':'Включить тёмную тему');b.title=dark?'Светлая тема':'Тёмная тема'});document.querySelectorAll('[data-action="set-theme"]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===activeTheme())));const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=dark?'#191d23':'#f8f8f8'}
