const calc=d=>(d?.lines||[]).reduce((a,l)=>a+(+l.qty||0)*(+l.rate||0),0)*(1-(+d?.discount||0)/100);
const partner=(d,kind='orders')=>(db[kindMeta[kind]?.partner||'customers']||[]).find(p=>p.id===d?.partner);
const item=id=>db.items.find(i=>i.id===id);
function paymentTotal(source){return db.payments.filter(p=>p.source===source&&p.state!=='cancelled').reduce((a,p)=>a+(p.direction==='out'?-p.amount:p.amount),0)}
function paid(d,kind='orders'){if(kind==='invoices')return paymentTotal(d.source||d.id);if(kind==='purchaseOrders')return +d.paid||0;return paymentTotal(d.id)}
const due=(d,kind='orders')=>Math.max(0,calc(d)-paid(d,kind));
function status(d,kind='orders'){if(d.state==='draft')return {text:'Черновик',tone:'red',key:'draft'};if(d.state==='closed')return {text:'Закрыт',tone:'',key:'closed'};if(kind==='quotes')return {text:d.converted?'Принято':'Отправлено',tone:d.converted?'green':'blue',key:d.converted?'completed':'open'};if(kind==='receipts'||kind==='stockDocs')return {text:'Подтверждён',tone:'green',key:'completed'};if(kind==='invoices')return due(d,kind)<.01?{text:'Оплачена',tone:'green',key:'completed'}:{text:'Ожидает оплаты',tone:'orange',key:'open'};if(d.delivered>=100)return {text:'Завершён',tone:'green',key:'completed'};return {text:d.delivered>0?'Частично выполнен':kind==='purchaseOrders'?'Ожидает поступления':'К выполнению',tone:'orange',key:'open'}}
function persist(){if(!put('erpbasic-v2',db)){toast('Не удалось сохранить данные: хранилище браузера недоступно.',true);return false}return true}
