function link(module,page,id){return '#/'+module+'/'+page+(id?'/'+encodeURIComponent(id):'')}
function navigate(module,page='home',id){if(dirty){ask('Несохранённые изменения','Сохраните документ, чтобы изменения остались в нём.',()=>{dirty=false;location.hash=link(module,page,id)},'Выйти без сохранения');return}location.hash=link(module,page,id);if(location.hash===link(module,page,id)&&route.module===module&&route.page===page&&route.id===id)render()}
function parseRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/').map(x=>decodeURIComponent(x));return {module:modules[parts[0]]?parts[0]:'sales',page:parts[1]||'home',id:parts[2]||null}}
function routeChanged(){const next=parseRoute();if(next.module!==route.module||next.page!==route.page){listState={search:'',status:'all',sort:'date',dir:-1,view:'list',limit:20,page:1,onlyLow:false};selected.clear()}route=next;draft=null;dirty=false;docTab='details';currentMenu='';showSidebar=false;render();window.scrollTo(0,0)}
function nextId(kind){const pref=kindMeta[kind]?.prefix||kind.toUpperCase().slice(0,3);const ns=(db[kind]||[]).map(d=>+d.id.split('-').pop()).filter(Number.isFinite);return pref+'-2026-'+String(Math.max(0,...ns)+1).padStart(4,'0')}
function renderShell(body,actions,title,doc=false){const m=modules[route.module];let nav=m.links.map(([p,n,ic])=>`<a class="side-item ${route.page===p?'active':''}" href="${link(route.module,p)}">${icon(ic)}<span>${n}</span>${p==='orders'?`<span class="count">${db.orders.length}</span>`:''}</a>`).join('');if(db.favorites.length&&!doc)nav+=`<div class="side-caption">Избранное</div>`+db.favorites.slice(0,4).map(id=>{const d=db.orders.find(o=>o.id===id);return d?`<a class="side-item" href="${link('sales','orders',id)}">${icon('heart')}<span>${esc(partner(d)?.name||id)}</span></a>`:''}).join('');$('#app').innerHTML=`<nav class="rail" aria-label="Модули"><a class="brand" href="${link('sales','home')}" title="ERPbasic">${icon('list')}</a><div class="rail-divider"></div>${Object.entries(modules).map(([key,mod])=>`<a class="rail-link ${route.module===key?'active':''}" href="${link(key,'home')}" aria-label="${mod.name}" title="${mod.name}">${icon(mod.icon)}<span class="tip">${mod.name}</span></a>`).join('')}<div class="rail-bottom"><button class="rail-link" data-action="search" aria-label="Поиск" title="Поиск · Ctrl K">${icon('search')}</button><button class="rail-link" data-action="help" aria-label="Помощь">${icon('help')}</button><button class="avatar" data-action="user-menu" aria-label="Меню пользователя">АК</button></div></nav><div class="mobile-overlay ${showSidebar?'visible':''}" data-action="sidebar-toggle"></div><aside class="sidebar ${doc?'document-hidden':''} ${showSidebar?'open':''}"><div class="side-title">${m.name}${icon('down')}</div><div class="side-tools"><button class="side-action" data-action="search">${icon('search')}Поиск <span class="kbd">⌘ K</span></button><button class="side-action" data-action="notifications">${icon('bell')}Уведомления <span class="count badge">${db.sync.filter(s=>s.state==='waiting').length}</span></button></div><nav class="side-nav" aria-label="${m.name}">${nav}</nav><div class="side-footer"><div class="side-company">${esc(db.company)}</div><div class="side-foot-line">ERP Basic ${badge(db.profile)} <span class="erp-push-right">5 мест</span></div><div class="side-foot-line erp-mt-10"><span class="local-dot"></span> Демонстрационные данные</div></div></aside><main class="workspace ${doc?'document':''}" id="content"><header class="topbar"><div class="top-title">${!doc?`<button class="icon-btn mobile-toggle" data-action="sidebar-toggle" aria-label="Меню раздела">${icon('menu')}</button>`:''}${title}</div><div class="actions">${themeToggle()}${actions||''}</div></header>${body}</main>`;document.title=(doc?kindMeta[route.page]?.singular:kindMeta[route.page]?.name||m.name)+' — ERPbasic';bindPage();updateThemeControls()}
function render(){if(route.id&&kindMeta[route.page]?.prefix){renderDocument();return}if(route.module==='settings'){renderSettings();return}if(route.module==='sync'){renderSync();return}if(route.page==='dashboard'){renderDashboard();return}if(route.page==='home'){renderWorkspace();return}if(route.page==='reports'||['receivables','payables'].includes(route.page)){renderReport();return}if(route.page==='inventory'){renderInventory();return}if(route.page==='warehouses'){renderWarehouses();return}if(kindMeta[route.page]){renderList();return}route.page='home';renderWorkspace()}
function metric(title,value,note,target=''){return `<${target?'a':'div'} class="metric" ${target?`href="${target}"`:''}><div class="metric-label">${title}${icon('more')}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></${target?'a':'div'}>`}
function trendChart(kind){const isStock=kind==='stock',isFinance=kind==='finance';const values=isStock?db.items.filter(i=>i.type==='Товар').map(i=>i.qty*i.cost):Array.from({length:10},(_,i)=>{const day='2026-11-'+String(i+1).padStart(2,'0');return (isFinance?db.payments.filter(p=>p.date===day).reduce((a,p)=>a+p.amount,0):db.orders.filter(o=>o.date===day).reduce((a,o)=>a+calc(o),0))});const max=Math.max(...values,10000),coords=values.map((v,i)=>`${40+i*(690/Math.max(1,values.length-1))},${140-v/max*120}`).join(' ');return `<div class="chart-card"><div class="card-title">${isStock?'Стоимость запасов по группам':isFinance?'Поступления денег':'Динамика заказов'}<span class="small muted">${isStock?'Основной склад':'Ноябрь 2026'}</span></div><div class="chart"><svg viewBox="0 0 760 180" preserveAspectRatio="none" role="img" aria-label="${isStock?'Стоимость запасов':'Динамика за ноябрь по демонстрационным документам'}"><defs><linearGradient id="chartFade" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--chart-color)" stop-opacity=".12"/><stop offset="100%" stop-color="var(--chart-color)" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<line x1="40" y1="${y}" x2="735" y2="${y}"/><text x="0" y="${y+3}">${money(max*(1-i/3)/1000,false)}к</text>`).join('')}<polygon class="chart-area" points="40,140 ${coords} 730,140"/><polyline class="chart-line" points="${coords}"/>${values.map((v,i)=>`<circle class="chart-dot" cx="${40+i*690/Math.max(1,values.length-1)}" cy="${140-v/max*120}" r="3"><title>${money(v)}</title></circle>`).join('')}${(isStock?db.items.filter(i=>i.type==='Товар'):values).map((v,i)=>`<text x="${40+i*690/Math.max(1,values.length-1)}" y="166" text-anchor="middle">${isStock?esc(v.id.slice(-3)):String(i+1).padStart(2,'0')+' ноя'}</text>`).join('')}</svg></div></div>`}
function workspaceCard(title,links){return `<div class="link-card"><h3>${title}</h3>${links.map(([label,p,mod])=>`<a class="card-link" href="${link(mod||route.module,p)}">${label}${icon('arrow')}</a>`).join('')}</div>`}
function shortcut(label,ic,page,count,mod=route.module){return `<a class="shortcut" href="${link(mod,page)}">${icon(ic)}<span>${label}</span>${count!==undefined?badge(count):icon('arrow')}</a>`}
function renderWorkspace(){const m=route.module,low=db.items.filter(i=>i.type==='Товар'&&i.qty<i.min),open=db.orders.filter(o=>status(o).key==='open'),sum=db.orders.filter(o=>o.state!=='draft').reduce((a,o)=>a+calc(o),0),debt=db.orders.filter(o=>o.state!=='draft').reduce((a,o)=>a+due(o),0);let cards='',shortcuts='',metrics='',notice='',recent='';if(m==='sales'){metrics=metric('Заказы клиентов',db.orders.length,open.length+' ожидают выполнения',link(m,'orders'))+metric('Сумма заказов',money(sum),'Подтверждённые заказы · ноябрь',link(m,'reports'))+metric('К оплате по заказам',money(debt),'Включая авансы и частичные оплаты',link('finance','receivables'));shortcuts=shortcut('Предложения','paper','quotes',db.quotes.length)+shortcut('Заказы клиентов','sales','orders',open.length+' открыто')+shortcut('Реализации','paper','invoices',db.invoices.length)+shortcut('Клиенты','users','customers',db.customers.length);cards=workspaceCard('Продажи',[['Клиенты','customers'],['Предложения','quotes'],['Заказы клиентов','orders'],['Реализации','invoices']])+workspaceCard('Товары и цены',[['Товары и услуги','items'],['Остатки на складах','balances','stock'],['Закупки под заказ','purchaseOrders','buying']])+workspaceCard('Отчёты и расчёты',[['Продажи и прибыль','reports'],['Долги клиентов','receivables','finance'],['Оплаты клиентов','payments','finance'],['Обмен с Clientora','home','sync']]);notice=`<div class="notice-card"><span class="notice-icon">${icon('clock')}</span><div><strong>${open.length} ${open.length===1?'заказ требует':'заказа требуют'} выполнения</strong><p>Контролируйте готовность, реализацию и оплату отдельно.</p></div>${button('Открыть заказы','open-orders','small outline','arrow')}</div>`;recent=`<div class="recent"><div class="card-title">Последние заказы<a class="small muted" href="${link('sales','orders')}">Все заказы ↗</a></div>${miniOrders(db.orders.slice(0,4))}</div>`}else if(m==='buying'){const outstanding=db.purchaseOrders.filter(d=>d.delivered<100);metrics=metric('Ожидают поступления',outstanding.length,'Заказы поставщикам',link(m,'purchaseOrders'))+metric('Заказано',money(db.purchaseOrders.reduce((a,o)=>a+calc(o),0)),'В текущем периоде',link(m,'reports'))+metric('Долг поставщикам',money(db.purchaseOrders.reduce((a,o)=>a+due(o,'purchaseOrders'),0)),'По подтверждённым заказам',link('finance','payables'));shortcuts=shortcut('Заказы поставщикам','buying','purchaseOrders',db.purchaseOrders.length)+shortcut('Поступления','box','receipts',db.receipts.length)+shortcut('Поставщики','users','suppliers',db.suppliers.length)+shortcut('Номенклатура','tag','items');cards=workspaceCard('Закупки',[['Заказы поставщикам','purchaseOrders'],['Поступления товаров','receipts'],['Поставщики','suppliers']])+workspaceCard('Планирование',[['Товары к пополнению','balances','stock'],['Номенклатура','items'],['Склады','warehouses','stock']])+workspaceCard('Отчёты и расчёты',[['Анализ закупок','reports'],['Долги поставщикам','payables','finance'],['Расходы компании','expenses','finance']])}else if(m==='stock'){const stock=db.items.filter(i=>i.type==='Товар');metrics=metric('Стоимость запасов',money(stock.reduce((a,i)=>a+i.qty*i.cost,0)),'По учётной стоимости',link(m,'balances'))+metric('Товаров в наличии',stock.length,'Номенклатурных позиций',link(m,'items'))+metric('Требуют пополнения',low.length,'Ниже минимального остатка',link(m,'balances'));shortcuts=shortcut('Остатки','stock','balances')+shortcut('Поступления','box','receipts',db.receipts.length)+shortcut('Движения товаров','branch','stockDocs',db.stockDocs.length)+shortcut('Инвентаризация','check','inventory');cards=workspaceCard('Товары и склады',[['Номенклатура','items'],['Остатки','balances'],['Склады','warehouses']])+workspaceCard('Операции',[['Поступления','receipts'],['Движения товаров','stockDocs'],['Инвентаризация','inventory']])+workspaceCard('Отчёты',[['Остатки и стоимость','reports'],['Закупки для пополнения','purchaseOrders','buying'],['Заказы клиентов','orders','sales']]);notice=`<div class="notice-card"><span class="notice-icon">${icon('stock')}</span><div><strong>${low.length} позиция ниже минимального остатка</strong><p>Проверьте потребность перед следующей закупкой.</p></div>${button('Посмотреть','low-stock','small outline','arrow')}</div>`}else if(m==='finance'){const income=db.payments.filter(p=>p.direction==='in').reduce((a,p)=>a+p.amount,0),expense=db.expenses.reduce((a,e)=>a+e.amount,0);metrics=metric('Поступления',money(income),'За текущий период',link(m,'payments'))+metric('Расходы',money(expense),'Операционные расходы',link(m,'expenses'))+metric('Деньги на счетах',money(db.settings.bankOpening+db.settings.cashOpening+income-expense),'Начальный остаток + движение',link(m,'reports'));shortcuts=shortcut('Оплаты','finance','payments',db.payments.length)+shortcut('Расходы','paper','expenses',db.expenses.length)+shortcut('Долги клиентов','clock','receivables')+shortcut('Долги поставщикам','clock','payables');cards=workspaceCard('Деньги',[['Оплаты','payments'],['Расходы','expenses'],['Движение денег','reports']])+workspaceCard('Взаиморасчёты',[['Долги клиентов','receivables'],['Долги поставщикам','payables'],['Реализации','invoices','sales']])+workspaceCard('Данные',[['Импорт выписки CSV','data','settings'],['Выгрузка данных','data','settings'],['Настройки компании','home','settings']])}
 const onboarding=!db.onboardingDismissed&&m==='sales'?`<div class="onboard"><div class="card-title"><h2>Начните работу со своим бизнесом</h2><button class="btn link small" data-action="dismiss-onboarding">Скрыть</button></div><p class="small muted erp-m-0">Настройте компанию, добавьте позиции и создайте первый заказ.</p><div class="onboard-progress"><span class="done"></span><span class="done"></span><span></span></div><div class="onboard-steps"><a href="${link('settings','home')}">✓ Компания</a><a href="${link('sales','items')}">✓ Товары и услуги</a><button data-action="new-document" class="btn link small">Создать заказ →</button></div></div>`:'';
 const head=`<strong>${modules[m].name}</strong>`;const act=`<span class="badge hide-mobile">${esc(db.profile)}</span>${button('Настроить','workspace-settings','small','more')}`;
 renderShell(`<div class="home-content"><div class="home-intro"><div><p class="eyebrow">${esc(db.company)}</p><h1>${m==='sales'?(db.profile==='Услуги'?'Продажи и услуги':'Продажи'):modules[m].name}</h1><span class="muted small">${m==='sales'?'От предложения клиенту до реализации и оплаты.':m==='stock'?'Товары, остатки и движения на складах.':m==='buying'?'Поставщики, заказы и поступления.':'Платежи, расходы и взаиморасчёты.'}</span></div>${badge('Ноябрь 2026')}</div>${onboarding}${notice}<div class="section-label">Быстрый доступ</div><div class="shortcut-row">${shortcuts}</div>${trendChart(m)}<div class="cards">${metrics}</div><div class="section-label">Документы, справочники и отчёты</div><div class="cards">${cards}</div>${recent}<footer class="page-footer"><span>ERPbasic · профиль «${esc(db.profile)}»</span><span class="demo-label"><span class="local-dot"></span>Демонстрация · данные в этом браузере</span></footer></div>`,act,head)}
function miniOrders(arr){return `<div class="table-scroller erp-p-0"><table><thead><tr><th>Клиент</th><th>Статус</th><th class="number">Сумма</th><th>Номер</th></tr></thead><tbody>${arr.map(o=>{let s=status(o);return `<tr><td class="main-cell"><a class="row-link" href="${link('sales','orders',o.id)}">${esc(partner(o)?.name)}</a></td><td>${badge(s.text,s.tone)}</td><td class="number">${money(calc(o))}</td><td class="doc-id"><a href="${link('sales','orders',o.id)}">${o.id}</a></td></tr>`}).join('')}</tbody></table></div>`}
const listColumns={
 docs:[['partner','Клиент'],['status','Статус'],['delivery','Дата выполнения'],['sum','Сумма'],['delivered','% Выполнено'],['billed','% Реализовано'],['id','Номер']],
 invoices:[['partner','Клиент'],['status','Статус'],['date','Дата'],['sum','Сумма'],['paid','Оплачено'],['debt','К оплате'],['id','Номер']],
 purchaseOrders:[['partner','Поставщик'],['status','Статус'],['delivery','Дата поставки'],['sum','Сумма'],['delivered','% Получено'],['debt','К оплате'],['id','Номер']],
 quotes:[['partner','Клиент'],['status','Статус'],['date','Дата'],['delivery','Действует до'],['sum','Сумма'],['id','Номер']],
 receipts:[['partner','Поставщик'],['status','Статус'],['date','Дата'],['sum','Сумма'],['source','Заказ поставщику'],['id','Номер']],
 items:[['name','Наименование'],['type','Тип'],['unit','Ед. изм.'],['price','Цена продажи'],['cost','Учётная стоимость'],['id','Код']],
 balances:[['name','Номенклатура'],['warehouse','Склад'],['qty','Остаток'],['reserved','Резерв'],['available','Доступно'],['valuation','Стоимость'],['stockStatus','Состояние']],
 customers:[['name','Наименование'],['contact','Контактное лицо'],['phone','Телефон'],['city','Город'],['clientDebt','К оплате по заказам']],
 suppliers:[['name','Наименование'],['contact','Контактное лицо'],['phone','Телефон'],['city','Город'],['supplierDebt','К оплате по заказам']],
 payments:[['id','Номер'],['party','Контрагент'],['date','Дата'],['account','Счёт'],['purpose','Назначение'],['amount','Сумма']],
 expenses:[['id','Номер'],['category','Статья'],['date','Дата'],['account','Счёт'],['purpose','Назначение'],['amount','Сумма']],
 stockDocs:[['id','Номер'],['operation','Операция'],['date','Дата'],['warehouse','Склад'],['status','Статус'],['source','Основание']],
 queue:[['source','Документ'],['entity','Объект'],['direction','Направление'],['syncStatus','Состояние'],['updated','Обновлено']]
};
function columnsFor(kind){const all=listColumns[kind]||listColumns.docs;const saved=db.views[kind]?.columns;return saved?all.filter(([k])=>saved.includes(k)):all}
function listData(){const kind=route.page;let data=kind==='balances'?db.items.filter(i=>i.type==='Товар'):kind==='queue'?db.sync:db[kind]||[];const q=listState.search.trim().toLocaleLowerCase('ru');data=data.filter(d=>{const text=[d.name,d.id,d.source,d.purpose,d.contact,d.city,partner(d,kind)?.name,d.entity].join(' ').toLocaleLowerCase('ru');if(q&&!text.includes(q))return false;if(listState.onlyLow&&!(d.qty<d.min))return false;if(listState.status!=='all'){if(kind==='items'&&d.type!==listState.status)return false;else if(kind==='queue'&&d.state!==listState.status)return false;else if(kindMeta[kind]?.prefix&&status(d,kind).key!==listState.status)return false}return true});const sort=listState.sort;data=[...data].sort((a,b)=>{let av=rawCell(a,sort,kind),bv=rawCell(b,sort,kind);return(typeof av==='number'?av-bv:String(av).localeCompare(String(bv),'ru'))*listState.dir});return data}
function billedPct(d){return Math.min(100,Math.round(db.invoices.filter(i=>i.source===d.id&&i.state==='submitted').reduce((a,i)=>a+calc(i),0)/Math.max(1,calc(d))*100))}
function percent(n){const value=Math.max(0,Math.min(100,Number(n)||0));return `<progress class="progress erp-progress" max="100" value="${value}" title="${value}%" aria-label="Выполнение: ${value}%">${value}%</progress>`}
function cell(d,k,kind){const s=status(d,kind),pr=partner(d,kind);switch(k){case 'partner':return `<a class="row-link" href="${link(route.module,kind,d.id)}">${esc(pr?.name||'Не указан')}</a>`;case 'status':return badge(s.text,s.tone);case 'date':case 'delivery':return dateText(d[k]);case 'sum':return money(calc(d));case 'paid':return money(paid(d,kind));case 'debt':return money(due(d,kind));case 'delivered':return percent(d.delivered);case 'billed':return percent(billedPct(d));case 'id':return `<span class="doc-id">${esc(d.id)}</span>`;case 'name':return `<a class="row-link" href="#" data-action="${kind==='balances'?'edit-item':'edit-record'}" data-id="${esc(d.id)}">${esc(d.name)}</a>`;case 'price':case 'cost':return money(d[k]);case 'warehouse':return esc(d.warehouse||'Основной склад');case 'available':return d.qty-d.reserved;case 'valuation':return money(d.qty*d.cost);case 'stockStatus':return d.qty<d.min?badge('Пополнить','orange'):badge('В наличии','green');case 'clientDebt':return money(db.orders.filter(o=>o.partner===d.id&&o.state!=='draft').reduce((a,o)=>a+due(o),0));case 'supplierDebt':return money(db.purchaseOrders.filter(o=>o.partner===d.id&&o.state!=='draft').reduce((a,o)=>a+due(o,'purchaseOrders'),0));case 'party':return esc(db.customers.find(c=>c.id===d.partner)?.name||d.partner);case 'amount':return `<span class="${kind==='payments'&&d.direction!=='out'?'good':''}">${kind==='payments'?(d.direction==='out'?'− ':'+ '):''}${money(d.amount)}</span>`;case 'source':return d.source?`<a class="focus-link" href="${link(d.source.startsWith('PO')?'buying':'sales',d.source.startsWith('PO')?'purchaseOrders':'orders',d.source)}">${esc(d.source)}</a>`:'—';case 'syncStatus':return badge(d.state==='done'?'Отражено':d.state==='waiting'?'Ожидает передачи':'Требует исправления',d.state==='done'?'green':d.state==='waiting'?'orange':'red');default:return esc(d[k]||'—')}}
function renderList(){const k=route.page,meta=kindMeta[k];const filterOptions=k==='items'?'<option value="all">Все типы</option><option>Товар</option><option>Услуга</option>':k==='queue'?'<option value="all">Все состояния</option><option value="waiting">Ожидает передачи</option><option value="done">Отражено</option>':'<option value="all">Все статусы</option><option value="draft">Черновик</option><option value="open">Открытые</option><option value="completed">Завершённые</option><option value="closed">Закрытые</option>';
 const toolbar=`${['orders','quotes','purchaseOrders','invoices'].includes(k)?`<select class="btn hide-mobile" id="list-view" aria-label="Представление"><option value="list" ${listState.view==='list'?'selected':''}>≡ Список</option><option value="kanban" ${listState.view==='kanban'?'selected':''}>▥ Канбан</option></select>`:''}<button class="btn hide-mobile" data-action="columns">Колонки ${icon('down')}</button><button class="icon-btn hide-mobile" data-action="refresh" aria-label="Обновить">${icon('refresh')}</button><div class="menu-wrap"><button class="icon-btn" data-action="list-menu" aria-label="Действия списка">${icon('more')}</button>${currentMenu==='list'?`<div class="dropdown">${button('Экспорт CSV','export-list','','download')}${button('Импорт данных','import-data','','upload')}${button('Печать','print','','print')}</div>`:''}</div>${k==='payments'?button('Возврат','refund-payment','','refresh'):''}${meta.add?button(meta.add,'new-document','primary','plus'):k==='stockDocs'?button('Добавить движение','stock-operation','primary','plus'):''}`;
 const filters=`<div class="filterbar"><input class="filter search" id="list-search" value="${esc(listState.search)}" placeholder="Поиск по названию или номеру" aria-label="Поиск в списке">${kindMeta[k]?.prefix||['items','queue'].includes(k)?`<select class="filter" id="list-status" aria-label="Фильтр статуса">${filterOptions}</select>`:''}${k==='balances'?`<label class="switch"><input id="only-low" type="checkbox" ${listState.onlyLow?'checked':''}> Ниже минимума</label>`:''}<div class="spacer"></div><button class="btn small" data-action="advanced-filters">${icon('filter')}Фильтр</button><button class="btn small" data-action="sort">${icon('sort')}Сортировка</button></div><div class="filter-summary"><span>${esc(db.company)}</span><span>·</span><span>${k==='balances'?'Основной склад':'Ноябрь 2026'}</span><span id="filter-count" class="erp-push-right"></span></div>`;
 renderShell(`<div class="list-content">${filters}<div id="list-selection"></div><div id="list-data"></div><div class="pagination" id="list-footer"></div></div>`,toolbar,`<strong>${meta.name}</strong>`);if($('#list-status'))$('#list-status').value=listState.status;updateList()}
function updateList(){const k=route.page,data=listData();const pg=Math.max(1,Math.min(listState.page,Math.ceil(data.length/listState.limit)||1));listState.page=pg;const shown=data.slice((pg-1)*listState.limit,pg*listState.limit),cols=columnsFor(k);$('#filter-count').textContent=data.length+' '+plural(data.length,'запись','записи','записей');$('#list-selection').innerHTML=selected.size?`<div class="selection-bar"><strong>Выбрано: ${selected.size}</strong>${button('Экспорт выбранных','export-selected','small','download')}${button('Снять выделение','clear-selection','small')}</div>`:'';
 if(listState.view==='kanban'&&kindMeta[k]?.prefix){$('#list-data').innerHTML=`<div class="view-kanban">${[['draft','Черновики'],['open','В работе'],['completed','Завершены']].map(([key,name])=>`<section class="kanban-col"><h3>${name} · ${data.filter(d=>status(d,k).key===key).length}</h3>${data.filter(d=>status(d,k).key===key).map(d=>`<a class="kanban-card" href="${link(route.module,k,d.id)}">${esc(partner(d,k)?.name)}<small>${d.id}</small>${badge(status(d,k).text,status(d,k).tone)}<div>${money(calc(d))}</div></a>`).join('')}</section>`).join('')}</div>`}else{$('#list-data').innerHTML=data.length?`<div class="table-scroller"><table><thead><tr><th class="check-cell"><input type="checkbox" data-action="select-all" aria-label="Выбрать все на странице" ${shown.length&&shown.every(d=>selected.has(d.id))?'checked':''}></th>${cols.map(([key,title])=>`<th class="${['sum','paid','debt','price','cost','amount','valuation','qty','reserved','available','clientDebt','supplierDebt'].includes(key)?'number':''}"><button class="column-sort" data-action="column-sort" data-id="${key}">${title}${listState.sort===key?icon(listState.dir===1?'up':'down'):''}</button></th>`).join('')}<th class="erp-col-28"></th></tr></thead><tbody>${shown.map(d=>`<tr ${kindMeta[k]?.prefix?`data-open="${esc(d.id)}"`:''} class="${k==='balances'&&d.qty<d.min?'low-highlight':''}"><td class="check-cell"><input type="checkbox" data-action="select-row" data-id="${esc(d.id)}" ${selected.has(d.id)?'checked':''} aria-label="Выбрать ${esc(d.name||d.id)}"></td>${cols.map(([key])=>`<td class="${['partner','name'].includes(key)?'main-cell ':''}${['sum','paid','debt','price','cost','amount','valuation','qty','reserved','available','clientDebt','supplierDebt'].includes(key)?'number':''}">${cell(d,key,k)}</td>`).join('')}<td>${k==='orders'?`<button class="star ${db.favorites.includes(d.id)?'selected':''}" data-action="favorite" data-id="${d.id}" aria-label="${db.favorites.includes(d.id)?'Убрать из избранного':'В избранное'}">${icon('heart')}</button>`:k==='queue'&&d.state!=='done'?`<button class="icon-btn" data-action="retry-one" data-id="${d.id}" aria-label="Повторить передачу">${icon('refresh')}</button>`:['customers','suppliers','items','balances'].includes(k)?`<button class="icon-btn" data-action="${k==='balances'?'edit-item':'edit-record'}" data-id="${esc(d.id)}" aria-label="Изменить">${icon('edit')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('list')}<strong>Записей пока нет</strong><div class="small erp-summary-gap">${listState.search?'Измените поисковый запрос или фильтры.':'Создайте первый документ или загрузите данные.'}</div>${kindMeta[k].add?button(kindMeta[k].add,'new-document','outline','plus'):''}</div>`}
 $('#list-footer').innerHTML=`<div class="erp-flex-4">${[20,100,500].map(n=>`<button class="btn ${n===listState.limit?'':'link'}" data-action="page-size" data-id="${n}">${n}</button>`).join('')}</div><div class="erp-flex-10"><span>${data.length?((pg-1)*listState.limit+1)+'–'+Math.min(pg*listState.limit,data.length):0} из ${data.length}</span><button class="icon-btn" data-action="prev-page" ${pg<=1?'disabled':''} aria-label="Предыдущая страница">${icon('back')}</button><button class="icon-btn" data-action="next-page" ${pg*listState.limit>=data.length?'disabled':''} aria-label="Следующая страница">${icon('chevron')}</button></div>`;
}
function plural(n,a,b,c){const k=n%100;return k>=11&&k<=14?c:n%10===1?a:n%10>=2&&n%10<=4?b:c}
function labeled(label,name,value,type='text',required=false,extra=''){return `<label class="field">${label}${required?' <span class="required">*</span>':''}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function blankDoc(kind){return {id:nextId(kind),kind,partner:'',date:DEMO_DATE,delivery:'2026-11-12',lines:[{item:'',qty:1,rate:0}],discount:0,warehouse:'Основной склад',state:'draft',delivered:0,paid:0,notes:'',terms:'',owner:'Алексей Курносов',history:[]}}
let pendingNew=null;
function newDoc(kind,source){if(dirty){toast('Сначала сохраните текущий документ');return}let d=blankDoc(kind);if(source){d={...structuredClone(source),id:nextId(kind),kind,state:'draft',source:source.id,paid:0,delivered:0,history:[],date:DEMO_DATE};if(kind==='receipts')d.lines=d.lines.filter(l=>item(l.item)?.type!=='Услуга')}
 pendingNew=d;const mod=kind==='receipts'&&route.module==='stock'?'stock':kindMeta[kind]?.module||route.module;if(route.id==='new'&&route.page===kind){draft=d;docTab='details';render()}else location.hash=link(mod,kind,'new')}
function renderDocument(){const kind=route.page,meta=kindMeta[kind];if(!draft){draft=pendingNew&&pendingNew.kind===kind?pendingNew:route.id==='new'?blankDoc(kind):structuredClone((db[kind]||[]).find(d=>d.id===route.id));pendingNew=null}if(!draft){renderShell(`<div class="empty">${icon('paper')}Документ не найден<br><br><a class="btn" href="${link(route.module,kind)}">Вернуться к списку</a></div>`,'',`<strong>${meta.name}</strong>`);return}const d=draft,p=partner(d,kind),isNew=route.id==='new',s=status(d,kind),readonly=d.state!=='draft';
 const title=`<a class="breadcrumb-link" href="${link(route.module,kind)}">${meta.singular}</a><span class="slash">/</span><strong>${esc(p?.name||'Новый документ')}</strong>${badge(isNew?'Не сохранён':s.text,isNew?'red':s.tone)}`;
 let actions=`${button('К списку','back-to-list','hide-medium','back')}<div class="menu-wrap"><button class="btn" data-action="create-menu" ${isNew||d.state==='draft'?'disabled':''}>Создать ${icon('down')}</button>${currentMenu==='create'?`<div class="dropdown">${kind==='quotes'?button('Заказ клиента','convert-order','','sales'):''}${kind==='orders'?button('Реализацию','create-invoice','','paper')+button('Оплату','receive-payment','','finance')+button('Заказ поставщику','purchase-from-order','','buying'):''}${kind==='purchaseOrders'?button('Поступление','create-receipt','','box'):''}${kind==='invoices'?button('Оплату','receive-payment','','finance'):''}</div>`:''}</div><div class="menu-wrap"><button class="icon-btn" data-action="doc-menu" aria-label="Действия документа">${icon('more')}</button>${currentMenu==='doc'?`<div class="dropdown">${button('Дублировать','duplicate-document','','paper')}${button('Печать','print','','print')}${button('Экспорт JSON','export-document','','download')}${!isNew?button('Вернуть в черновик','amend-document','','edit'):''}</div>`:''}</div>${button(readonly?'Сохранено':isNew||dirty?'Сохранить':'Подтвердить',readonly?'saved':isNew||dirty?'save-document':'submit-document','primary',readonly?'check':'')}`;
 const inputParts=`<div class="form-grid"><label class="field">${meta.partner==='suppliers'?'Поставщик':'Клиент'} <span class="required">*</span><select name="partner" required ${readonly?'disabled':''}><option value="">Выберите ${meta.partner==='suppliers'?'поставщика':'клиента'}</option>${(db[meta.partner]||[]).map(p=>`<option value="${p.id}" ${p.id===d.partner?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small><button type="button" class="btn link small" data-action="add-doc-partner" ${readonly?'disabled':''}>+ Добавить ${meta.partner==='suppliers'?'поставщика':'клиента'}</button></small></label>${labeled('Дата документа','date',d.date,'date',true,readonly?'disabled':'')}<label class="field">Компания<input value="${esc(db.company)}" disabled></label>${labeled(kind==='quotes'?'Действует до':kind==='purchaseOrders'?'Дата поставки':'Дата выполнения','delivery',d.delivery,'date',true,readonly?'disabled':'')}<label class="field">Вид операции<select name="operation" ${readonly?'disabled':''}><option>${kind==='purchaseOrders'||kind==='receipts'?'Закупка':db.profile==='Услуги'?'Услуги и товары':'Продажа товаров'}</option></select></label><label class="field">Ответственный<input name="owner" value="${esc(d.owner||'Алексей Курносов')}" ${readonly?'disabled':''}></label></div>`;
 let content='';if(docTab==='details')content=`<form id="document-form"><section class="form-section">${inputParts}</section><details class="collapse-title"><summary>Валюта и условия расчёта ${icon('chevron')}</summary><div class="form-grid two"><label class="field">Валюта<input value="RUB · Российский рубль" disabled></label><label class="field">Вид цены<input value="Основная" disabled></label></div></details><section class="form-section"><h2>Товары и услуги</h2><div class="form-grid two"><label class="field">Склад<select name="warehouse" ${readonly?'disabled':''}><option>Основной склад</option></select></label><label class="field">Найти позицию по коду<input id="scan-item" placeholder="Код номенклатуры → Enter" ${readonly?'disabled':''}></label></div><div id="doc-lines">${renderDocLines(readonly)}</div>${!readonly?button('Добавить строку','add-line','small','plus'):''}<div class="totals"><div class="total-row"><span>Сумма позиций</span><span id="subtotal">${money(d.lines.reduce((a,l)=>a+l.qty*l.rate,0))}</span></div><div class="total-row"><label for="doc-discount">Скидка, %</label><input id="doc-discount" name="discount" type="number" min="0" max="100" step=".1" value="${d.discount||0}" ${readonly?'disabled':''} class="erp-discount-input"></div><div class="total-row"><span>НДС</span><span>Без НДС</span></div><div class="total-row grand"><span>Итого</span><span id="grand-total">${money(calc(d))}</span></div>${!isNew?`<div class="total-row"><span>Оплачено</span><span>${money(paid(d,kind))}</span></div>`:''}</div></section><section class="form-section"><h2>Дополнительно</h2><label class="field">Комментарий<textarea name="notes" placeholder="Внутреннее примечание к документу" ${readonly?'disabled':''}>${esc(d.notes)}</textarea></label></section></form>${renderTimeline(d)}`;
 if(docTab==='contacts')content=`<section class="form-section"><h2>Адрес и контакты ${meta.partner==='suppliers'?'поставщика':'клиента'}</h2><div class="form-grid two">${labeled('Контактное лицо','contact',p?.contact||'','text',false,'readonly')}${labeled('Телефон','phone',p?.phone||'','text',false,'readonly')}${labeled('Электронная почта','email',p?.email||'','text',false,'readonly')}${labeled('Город','city',p?.city||'','text',false,'readonly')}</div><p class="small muted erp-mt-20">${esc(p?.address||'Адрес не указан')}</p>${p?button('Изменить карточку контрагента','edit-doc-partner','outline small','edit'):''}</section>`;
 if(docTab==='terms')content=`<section class="form-section"><h2>Условия</h2><label class="field">Условия оплаты и выполнения<textarea id="doc-terms" ${readonly?'disabled':''}>${esc(d.terms||'Оплата по согласованным условиям.')}</textarea></label><div class="info-box">Счёт на оплату можно распечатать из заказа. Реализация и оплата оформляются отдельными документами.</div></section>`;
 if(docTab==='connections')content=renderConnections(d,kind);
 const metaPanel=`<aside class="doc-meta"><h3>${esc(p?.name||'Новый документ')}</h3><div class="meta-id">${d.id}</div><div class="meta-row">${icon('users')}Ответственный<br></div><div class="erp-list-note">${esc(d.owner||'Алексей Курносов')}</div><button class="meta-row" data-action="attachments">${icon('attach')}Вложения ${icon('plus')}</button><button class="meta-row" data-action="doc-tags">${icon('tag')}Метки ${d.tags?badge(d.tags):icon('plus')}</button><div class="meta-block">Создал Алексей Курносов<br>${dateText(d.date)}<br><br>Компания<br><span class="erp-text-muted">${esc(db.company)}</span><br><br><span class="local-dot"></span> Демонстрационный документ</div></aside>`;
 renderShell(`<div class="doc-layout"><div class="doc-main"><div class="doc-banner ${readonly?'confirmed':''}">${readonly?'Документ подтверждён. Доступны следующие операции.':'Сохраните и подтвердите документ, чтобы продолжить работу.'}</div><nav class="tabs" aria-label="Вкладки документа">${[['details','Основное'],['contacts','Адрес и контакты'],['terms','Условия'],['connections','Связи']].map(([id,t])=>`<button class="tab ${docTab===id?'active':''}" data-action="doc-tab" data-id="${id}">${t}${id==='connections'?` <span class="muted">${connectionCount(d)}</span>`:''}</button>`).join('')}</nav>${content}</div>${metaPanel}</div>`,actions,title,true)}
function renderDocLines(readonly){return `<div class="items-table"><table><thead><tr><th class="erp-col-30">№</th><th>Номенклатура <span class="erp-text-warning">*</span></th><th class="number">Количество <span class="erp-text-warning">*</span></th><th>Ед.</th><th class="number">Цена</th><th class="number">Сумма</th><th></th></tr></thead><tbody>${draft.lines.map((l,i)=>`<tr><td class="erp-text-soft">${i+1}</td><td><select data-line="${i}" data-field="item" aria-label="Номенклатура строки ${i+1}" ${readonly?'disabled':''}><option value="">Выберите позицию</option>${db.items.filter(it=>!(route.page==='receipts'&&it.type==='Услуга')).sort((a,b)=>{const preferred=db.profile==='Услуги'?'Услуга':'Товар';return (b.type===preferred)-(a.type===preferred)}).map(it=>`<option value="${it.id}" ${l.item===it.id?'selected':''}>${esc(it.name)}</option>`).join('')}</select></td><td class="number"><input type="number" min=".001" step="any" data-line="${i}" data-field="qty" value="${l.qty}" aria-label="Количество строки ${i+1}" ${readonly?'disabled':''}></td><td>${esc(item(l.item)?.unit||'—')}</td><td class="number"><input type="number" min="0" step=".01" data-line="${i}" data-field="rate" value="${l.rate}" aria-label="Цена строки ${i+1}" ${readonly?'disabled':''}></td><td class="amount" id="line-amount-${i}">${money(l.qty*l.rate)}</td><td>${readonly?'':`<button type="button" class="icon-btn" data-action="remove-line" data-id="${i}" aria-label="Удалить строку ${i+1}">${icon('close')}</button>`}</td></tr>`).join('')}</tbody></table></div>`}
function renderTimeline(d){return `<section class="timeline"><h2>История и комментарии</h2>${route.id!=='new'?`<div class="comment-box"><input id="comment-text" placeholder="Добавить комментарий…" aria-label="Комментарий">${button('Добавить','comment','small outline')}</div>`:''}${[...(d.history||[])].reverse().map(h=>`<div class="timeline-entry"><strong>${esc(h.text)}</strong><small>Алексей Курносов · ${dateText(h.at?.slice(0,10))}</small></div>`).join('')||'<span class="small muted">История появится после сохранения.</span>'}</section>`}
function connectionCount(d){return db.invoices.filter(i=>i.source===d.id).length+db.payments.filter(p=>p.source===d.id||p.source===d.source).length+db.receipts.filter(p=>p.source===d.id).length+(d.source?1:0)}
function renderConnections(d,kind){const inv=db.invoices.filter(i=>i.source===d.id),pays=db.payments.filter(p=>p.source===d.id||(d.source&&p.source===d.source)),rec=db.receipts.filter(r=>r.source===d.id);return `<section class="connections"><h2>Связанные документы</h2>${d.source?`<a class="connection-card" href="${link(d.source.startsWith('PO')?'buying':'sales',d.source.startsWith('PO')?'purchaseOrders':d.source.startsWith('QUO')?'quotes':'orders',d.source)}"><span>Документ-основание<small>${esc(d.source)}</small></span>${icon('arrow')}</a>`:''}${inv.map(i=>`<a class="connection-card" href="${link('sales','invoices',i.id)}"><span>Реализация<small>${i.id} · ${dateText(i.date)}</small></span><span>${money(calc(i))}</span></a>`).join('')}${rec.map(i=>`<a class="connection-card" href="${link('buying','receipts',i.id)}"><span>Поступление<small>${i.id} · ${dateText(i.date)}</small></span><span>${money(calc(i))}</span></a>`).join('')}${pays.map(p=>`<div class="connection-card"><span>${p.direction==='out'?'Возврат оплаты':'Оплата'}<small>${p.id} · ${dateText(p.date)}</small></span><span>${money(p.amount)}</span></div>`).join('')}${!connectionCount(d)?'<div class="empty">Связанных документов пока нет.</div>':''}<div class="info-box">Новые реализации, поступления и оплаты создавайте из этого документа — связь с основанием сохранится.</div></section>`}
function captureDraft(){if(!draft)return;const f=$('#document-form');if(f){const fd=new FormData(f);for(const key of ['partner','date','delivery','warehouse','owner','notes'])if(fd.has(key))draft[key]=fd.get(key);if(fd.has('discount'))draft.discount=Number(fd.get('discount'))}if($('#doc-terms'))draft.terms=$('#doc-terms').value}
function markDirty(){dirty=true;const b=$('[data-action="submit-document"]');if(b){b.dataset.action='save-document';b.textContent='Сохранить'}}
function saveDocument(submit=false){captureDraft();let d=draft,kind=route.page;if(!d.partner){toast('Выберите контрагента',true);return}if(!d.date||!d.delivery){toast('Укажите дату документа и выполнения',true);return}if(!d.lines.length||d.lines.some(l=>!item(l.item)||!Number.isFinite(+l.qty)||+l.qty<=0||!Number.isFinite(+l.rate)||+l.rate<0)){toast('Проверьте номенклатуру, количество и цену в каждой строке',true);return}if(d.discount<0||d.discount>100){toast('Скидка должна быть от 0 до 100%',true);return}
 const current=(db[kind]||[]).find(r=>r.id===d.id);if(submit&&kind==='receipts'&&current?.state!=='submitted'){for(const l of d.lines){const it=item(l.item);if(it?.type==='Товар')it.qty+=+l.qty}if(d.source){const p=db.purchaseOrders.find(o=>o.id===d.source);if(p)p.delivered=100}}
 if(submit&&kind==='invoices'&&current?.state!=='submitted'){const needed={};for(const l of d.lines)needed[l.item]=(needed[l.item]||0)+Number(l.qty);for(const [id,qty] of Object.entries(needed)){const it=item(id);if(it?.type==='Товар'&&it.qty<qty){toast('Недостаточно товара: '+it.name,true);return}}for(const l of d.lines){const it=item(l.item);if(it?.type==='Товар'){it.qty-=+l.qty;it.reserved=Math.min(it.reserved,it.qty)}}if(d.source){const o=db.orders.find(r=>r.id===d.source);if(o)o.delivered=100}}
 if(submit&&kind==='orders'&&d.source?.startsWith('QUO')){const q=db.quotes.find(q=>q.id===d.source);if(q)q.converted=d.id}d.state=submit?'submitted':d.state;d.kind=kind;d.history=d.history||[];d.history.push({text:submit?'Документ подтверждён':current?'Изменения сохранены':'Документ создан',at:DEMO_DATE+'T11:00:00'});if(current)Object.assign(current,structuredClone(d));else db[kind].unshift(structuredClone(d));persist();dirty=false;const wasNew=route.id==='new';if(wasNew){location.hash=link(route.module,kind,d.id)}else{draft=structuredClone(d);render()}toast(submit?'Документ подтверждён':'Документ сохранён')}
let reportRange={start:'2026-11-01',end:'2026-11-30'},reportRows=[],reportHeads=[];
function renderReport(){const m=route.module,k=route.page;let report=route.id|| (m==='stock'?'stock':m==='buying'?'purchases':m==='finance'?'cash':'sales');if(k==='receivables'||k==='payables')report=k;const names={sales:'Продажи по заказам',profit:'Валовая прибыль по реализациям',stock:'Остатки и стоимость запасов',purchases:'Закупки и поступления',cash:'Движение денег',receivables:'К оплате по заказам клиентов',payables:'К оплате по заказам поставщиков'};const inRange=d=>(!d.date||d.date>=reportRange.start&&d.date<=reportRange.end);let rows=[],heads=[],metrics='',note='';if(report==='sales'){const arr=db.orders.filter(o=>o.state!=='draft'&&inRange(o));heads=['Номер','Клиент','Дата','Сумма заказа','Оплачено','К оплате'];rows=arr.map(o=>[o.id,partner(o)?.name,dateText(o.date),calc(o),paid(o),due(o)]);metrics=metric('Сумма заказов',money(arr.reduce((a,o)=>a+calc(o),0)),arr.length+' подтверждённых документов')+metric('Оплачено',money(arr.reduce((a,o)=>a+paid(o),0)),'По выбранным заказам')+metric('Осталось оплатить',money(arr.reduce((a,o)=>a+due(o),0)),'По выбранным заказам');note='Сумма заказов отражает обязательства клиентов. Доходы и прибыль смотрите по реализациям.'}else if(report==='profit'){const arr=db.invoices.filter(o=>o.state==='submitted'&&inRange(o));heads=['Реализация','Клиент','Выручка','Учётная стоимость','Валовая прибыль'];rows=arr.map(o=>{const cost=o.lines.reduce((a,l)=>a+(item(l.item)?.cost||0)*l.qty,0);return[o.id,partner(o,'invoices')?.name,calc(o),cost,calc(o)-cost]});const revenue=rows.reduce((a,r)=>a+r[2],0),cost=rows.reduce((a,r)=>a+r[3],0);metrics=metric('Выручка',money(revenue),'Подтверждённые реализации')+metric('Учётная стоимость',money(cost),'По стоимости позиций справочника')+metric('Валовая прибыль',money(revenue-cost),'Без операционных расходов');note='Демонстрационный расчёт использует стоимость из справочника. Партионная себестоимость будет рассчитываться учётным ядром.'}else if(report==='stock'){heads=['Код','Номенклатура','Остаток','Резерв','Доступно','Стоимость'];rows=db.items.filter(i=>i.type==='Товар').map(i=>[i.id,i.name,i.qty,i.reserved,i.qty-i.reserved,i.qty*i.cost]);metrics=metric('Стоимость запасов',money(rows.reduce((a,r)=>a+r[5],0)),'Текущие остатки')+metric('Товарных позиций',rows.length,'Основной склад')+metric('Требуют пополнения',db.items.filter(i=>i.type==='Товар'&&i.qty<i.min).length,'Ниже минимального остатка');note='Остатки показаны на текущий момент; фильтр дат к этому отчёту не применяется.'}else if(report==='purchases'){const arr=db.purchaseOrders.filter(inRange);heads=['Заказ','Поставщик','Дата поставки','Сумма','Получено, %','К оплате'];rows=arr.map(o=>[o.id,partner(o,'purchaseOrders')?.name,dateText(o.delivery),calc(o),o.delivered||0,due(o,'purchaseOrders')]);metrics=metric('Заказано',money(arr.reduce((a,o)=>a+calc(o),0)),'По заказам поставщикам')+metric('Подтверждённых поступлений',db.receipts.filter(inRange).filter(o=>o.state==='submitted').length,'В выбранном периоде')+metric('К оплате',money(arr.reduce((a,o)=>a+due(o,'purchaseOrders'),0)),'По заказам поставщикам')}else if(report==='receivables'||report==='payables'){const buying=report==='payables',arr=(buying?db.purchaseOrders:db.orders).filter(o=>o.state!=='draft'&&due(o,buying?'purchaseOrders':'orders')>0&&inRange(o));heads=['Заказ',buying?'Поставщик':'Клиент','Дата','Сумма','Оплачено','К оплате'];rows=arr.map(o=>[o.id,partner(o,buying?'purchaseOrders':'orders')?.name,dateText(o.date),calc(o),paid(o,buying?'purchaseOrders':'orders'),due(o,buying?'purchaseOrders':'orders')]);metrics=metric('К оплате',money(rows.reduce((a,r)=>a+r[5],0)),'По выбранным заказам')+metric('Открытых заказов',arr.length,'Есть неоплаченный остаток')+metric('Контрагентов',new Set(arr.map(o=>o.partner)).size,'С неоплаченными заказами');note='Показана сумма к оплате по заказам с учётом авансов. Бухгалтерская задолженность определяется проведёнными учётными документами.'}else{const ins=db.payments.filter(inRange),outs=db.expenses.filter(inRange);heads=['Дата','Документ','Назначение','Счёт','Приход','Расход'];rows=[...ins.map(p=>[dateText(p.date),p.id,p.purpose,p.account,p.direction==='in'?p.amount:0,p.direction==='out'?p.amount:0]),...outs.map(p=>[dateText(p.date),p.id,p.purpose,p.account,0,p.amount])];const income=rows.reduce((a,r)=>a+r[4],0),out=rows.reduce((a,r)=>a+r[5],0);metrics=metric('Поступления',money(income),'За выбранный период')+metric('Расходы и возвраты',money(out),'За выбранный период')+metric('Чистый денежный поток',money(income-out),'Поступления − расходы')}
 reportRows=rows;reportHeads=heads;const currencyCols=report==='stock'?[5]:report==='profit'?[2,3,4]:report==='cash'?[4,5]:report==='purchases'?[3,5]:[3,4,5];const tableHtml=`<div class="table-scroller erp-p-0"><table><thead><tr>${heads.map((h,i)=>`<th class="${currencyCols.includes(i)?'number':''}">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td class="${currencyCols.includes(i)?'number':''}">${currencyCols.includes(i)?money(v):esc(v)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${heads.length}" class="empty">Нет данных за выбранный период</td></tr>`}</tbody>${rows.length?`<tfoot><tr>${heads.map((_,i)=>`<td class="${currencyCols.includes(i)?'number':''}">${i===0?'Итого':currencyCols.includes(i)?money(rows.reduce((a,r)=>a+(+r[i]||0),0)):''}</td>`).join('')}</tr></tfoot>`:''}</table></div>`;
 renderShell(`<div class="report-content"><div class="filterbar erp-flat-start"><select id="report-select" class="filter" aria-label="Отчёт">${Object.entries(names).map(([v,n])=>`<option value="${v}" ${report===v?'selected':''}>${n}</option>`).join('')}</select><label class="small muted">С <input class="filter" type="date" id="report-start" value="${reportRange.start}" ${report==='stock'?'disabled':''}></label><label class="small muted">по <input class="filter" type="date" id="report-end" value="${reportRange.end}" ${report==='stock'?'disabled':''}></label>${button('Применить','apply-report','small outline')}</div><h1 class="report-title">${names[report]}</h1><p class="small muted">${esc(db.company)} · ${report==='stock'?'Текущее состояние':dateText(reportRange.start)+' — '+dateText(reportRange.end)}</p><div class="report-metrics">${metrics}</div>${tableHtml}${note?`<div class="info-box">${note}</div>`:''}<footer class="page-footer"><span>Управленческий отчёт</span><span>Демонстрационные данные</span></footer></div>`,button('Экспорт','export-report','','download')+button('Печать','print','hide-mobile','print'),`<strong>Отчёты</strong>`)}
function renderInventory(){const goods=db.items.filter(i=>i.type==='Товар');renderShell(`<div class="settings-content"><h1>Инвентаризация</h1><p class="muted small">Сверьте фактическое количество товаров с данными системы.</p><section class="settings-section"><div class="form-grid two">${labeled('Дата','date',DEMO_DATE,'date')}<label class="field">Склад<select><option>Основной склад</option></select></label></div><div class="items-table"><table><thead><tr><th>Номенклатура</th><th class="number">По учёту</th><th class="number">Фактически</th><th class="number">Разница</th></tr></thead><tbody>${goods.map(i=>`<tr><td>${esc(i.name)}</td><td class="number">${i.qty}</td><td><input type="number" min="${i.reserved}" step="1" value="${i.qty}" data-inventory="${i.id}" aria-label="Фактический остаток ${esc(i.name)}"></td><td class="number" id="diff-${i.id}">0</td></tr>`).join('')}</tbody></table></div><p class="small muted">Фактический остаток не может быть меньше зарезервированного количества.</p><label class="field">Комментарий<input id="inventory-note" placeholder="Например: плановая проверка склада"></label></section><div class="info-box">После подтверждения изменения попадут в остатки и журнал движений товаров.</div></div>`,button('Подтвердить инвентаризацию','save-inventory','primary','check'),`<strong>Инвентаризация</strong>`)}
function renderWarehouses(){renderShell(`<div class="settings-content"><h1>Склады</h1><p class="muted small">В Basic доступно до двух складов.</p><section class="settings-section"><div class="setting-row"><div><strong>Основной склад</strong><small>Основное место хранения · Санкт-Петербург</small></div>${badge('Активен','green')}</div><div class="setting-row"><div><strong>Резервный склад</strong><small>Дополнительное место хранения</small></div>${badge('Не используется')}</div></section><div class="info-box">Учёт товаров ведётся на «Основном складе». Движения доступны в отдельном журнале.</div><a class="btn outline" href="${link('stock','balances')}">${icon('stock')}Открыть остатки</a></div>`,'',`<strong>Склады</strong>`)}
function renderSettings(){const p=route.page;let title='Компания',body='',actions='';if(p==='home'){body=`<h1>Компания</h1><p class="muted small">Основные реквизиты и параметры работы.</p><section class="settings-section"><h2>Общая информация</h2><form id="company-form"><div class="form-grid two">${labeled('Наименование компании','company',db.company,'text',true)}${labeled('Город','city',db.city||'Санкт-Петербург')}<label class="field">Валюта<input value="RUB · Российский рубль" disabled></label><label class="field">Учёт<input value="Управленческий" disabled></label></div></form></section><section class="settings-section"><h2>Редакция и ресурсы</h2><div class="setting-row"><div><strong>ERP Basic</strong><small>1 компания · 5 внутренних пользователей · 2 склада</small></div><a class="btn" href="${link('settings','upgrade')}">Возможности Business ${icon('arrow')}</a></div><div class="setting-row"><div><strong>Подключённые продукты</strong><small>Clientora — запись, выполнение работ и общение</small></div><a class="btn link" href="${link('sync','home')}">Открыть</a></div></section>`;actions=button('Сохранить','save-company','primary')}else if(p==='team'){title='Команда и роли';body=`<h1>Команда и роли</h1><p class="muted small">Три демонстрационных сотрудника из пяти доступных мест.</p><section class="settings-section"><table><thead><tr><th>Сотрудник</th><th>Роль</th><th>Доступ</th></tr></thead><tbody><tr><td>Алексей Курносов</td><td>Владелец</td><td>Все разделы</td></tr><tr><td>Анна Смирнова</td><td>Менеджер</td><td>Продажи и клиенты</td></tr><tr><td>Сергей Иванов</td><td>Кладовщик</td><td>Товары и склад</td></tr></tbody></table></section><div class="info-box">В прототипе показаны примеры ролей. Приглашения и разграничение доступа подключаются при запуске рабочей системы.</div>`}else if(p==='profile'){title='Профиль работы';body=`<h1>Профиль работы</h1><p class="muted small">Настройте начальный акцент интерфейса под свою компанию.</p><section class="settings-section"><label class="field">Ваша деятельность<select id="profile-select"><option ${db.profile==='Услуги'?'selected':''}>Услуги</option><option ${db.profile==='Торговля'?'selected':''}>Торговля</option></select></label><p>«Услуги»: заказы, выполнение работ и материалы. Услуги стоят первыми в подборе номенклатуры.</p><p>«Торговля»: продажи, реализация и товары. Товарные позиции стоят первыми в подборе.</p></section><div class="info-box">Справочники и документы сохраняются при смене профиля.</div>`;actions=button('Сохранить профиль','save-profile','primary')}else if(p==='data'){title='Импорт и экспорт';body=`<h1>Данные</h1><p class="muted small">Загрузка справочников и банковских операций, выгрузка документов.</p><section class="settings-section"><h2>Импорт CSV</h2><div class="setting-row"><div><strong>Товары и услуги</strong><small>Код; Наименование; Тип; Единица; Цена; Стоимость</small></div>${button('Загрузить','import-items','outline','upload')}</div><div class="setting-row"><div><strong>Банковская выписка</strong><small>Дата; Заказ; Сумма; Счёт; Назначение</small></div>${button('Загрузить','import-bank','outline','upload')}</div></section><section class="settings-section"><h2>Экспорт и резервная копия</h2><div class="setting-row"><div><strong>Заказы клиентов</strong><small>Все заказы в CSV</small></div>${button('Скачать','export-orders','outline','download')}</div><div class="setting-row"><div><strong>Резервная копия данных</strong><small>Все демонстрационные справочники и операции в JSON</small></div>${button('Скачать','backup','outline','download')}</div><div class="setting-row"><div><strong>Восстановление копии</strong><small>Заменяет данные прототипа содержимым выбранной копии</small></div>${button('Выбрать копию','restore','outline','upload')}</div></section><div class="info-box">Изменения сохраняются в браузере на этом устройстве. Для совместной работы требуется серверная база.</div>`}else if(p==='upgrade'){title='ERP Business';body=`<h1>Растите вместе со своим бизнесом</h1><p class="muted small">Переход на расширенные процессы с сохранением справочников и документов.</p><div class="upgrade-grid"><div class="upgrade-card current">${badge('Текущая редакция')}<h2>ERP Basic</h2><div class="price">4 990 ₽ <small>/ месяц</small></div><ul><li>Одна компания</li><li>До 5 сотрудников и 2 складов</li><li>Продажи, закупки и запасы</li><li>Деньги и управленческие отчёты</li></ul></div><div class="upgrade-card"><span class="badge blue">Когда понадобится больше</span><h2>ERP Business</h2><div class="price">от 14 990 ₽ <small>/ месяц</small></div><ul><li>До 3 компаний одного заказчика</li><li>До 15 сотрудников и 10 складов</li><li>Производство, проекты и активы</li><li>Расширенные процессы ERP</li></ul>${button('Подготовить переход','upgrade-check','primary','check')}</div></div><section class="settings-section"><h2>Проверка перед переходом</h2><div class="checklist"><label><input type="checkbox" checked disabled> Справочники и документы доступны</label><label><input type="checkbox" checked disabled> У каждого документа есть постоянный идентификатор</label><label><input type="checkbox" id="upgrade-backup"> Резервная копия скачана</label><label><input type="checkbox" id="upgrade-process"> Новые процессы и ответственные определены</label></div></section><div class="info-box">Цены — предложение из ТЗ. Эта страница демонстрирует подготовку перехода; подписка и развёртывание полной ERP здесь не запускаются.</div>`}else{route.page='home';renderSettings();return}renderShell(`<div class="settings-content">${body}</div>`,actions,`<strong>${title}</strong>`)}
function renderSync(){let p=route.page;if(p==='queue'){renderList();return}let body='';if(p==='mapping'){body=`<h1>Соответствия объектов</h1><p class="muted small">Как распределяется ответственность в комплекте ERPbasic + Clientora.</p><section class="settings-section"><table><thead><tr><th>Объект</th><th>Основная система</th></tr></thead><tbody>${[['Клиенты и учётные реквизиты','ERP'],['Товары и остатки','ERP'],['Закупки и поступления','ERP'],['Финансовые документы','ERP'],['Запись и ресурсы','Clientora'],['Выполнение работ и фото','Clientora'],['Переписка','Clientora']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody></table></section><div class="info-box">Постоянные соответствия идентификаторов настраиваются при подключении интеграции.</div>`}else{body=`<h1>ERPbasic + Clientora</h1><p class="muted small">Один учёт, привычный экран для работы с клиентом.</p><section class="settings-section"><div class="setting-row"><div><strong>Подключение</strong><small>Демонстрационный режим</small></div>${badge('Не подключено','orange')}</div><div class="setting-row"><div><strong>Ожидают передачи</strong><small>Операции, которые ещё не отражены</small></div><a href="${link('sync','queue')}" class="btn outline">${db.sync.filter(s=>s.state==='waiting').length} операции ${icon('arrow')}</a></div><div class="setting-row"><div><strong>Стандартный обмен</strong><small>Заказы, оплаты, статусы и материалы</small></div>${badge('Включён в комплект','green')}</div></section><div class="cards">${workspaceCard('В Clientora',[['Запись и выполнение','mapping'],['Общение с клиентом','mapping']])}${workspaceCard('В ERP',[['Заказы клиентов','orders','sales'],['Оплаты','payments','finance']])}${workspaceCard('Контроль',[['Операции обмена','queue'],['Соответствия объектов','mapping']])}</div><div class="info-box">В прототипе можно просмотреть очередь и повторить демонстрационную передачу. Обмен с действующими системами пока не подключён.</div>`}renderShell(`<div class="settings-content">${body}</div>`,p==='home'?button('Обработать демо-очередь','retry-sync','','refresh'):'',`<strong>${p==='mapping'?'Соответствия':'Clientora'}</strong>`)}
function renderStockDocument(){const d=db.stockDocs.find(d=>d.id===route.id);renderShell(d?`<div class="settings-content"><h1>${esc(d.operation)}</h1><p class="muted small">${dateText(d.date)} · ${esc(d.warehouse)}</p><section class="settings-section"><table><thead><tr><th>Номенклатура</th><th class="number">Количество / изменение</th></tr></thead><tbody>${d.lines.map(l=>`<tr><td>${esc(item(l.item)?.name||l.item)}</td><td class="number">${l.qty>0?'+':''}${l.qty}</td></tr>`).join('')}</tbody></table></section><p class="small muted">${esc(d.notes||'')}</p></div>`:'<div class="empty">Документ не найден</div>',button('К списку','back-to-list','','back'),`<a class="breadcrumb-link" href="${link('stock','stockDocs')}">Движение товаров</a><span class="slash">/</span><strong>${esc(d?.id||'')}</strong>${badge('Подтверждён','green')}`,true)}
function openDialog(title,body,footer='',size=''){const el=$('#dialog');el.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div><div class="dialog-body ${size}">${body}</div><div class="dialog-foot">${button('Закрыть','close-dialog')}${footer}</div>`;if(!el.open)el.showModal();return el}
let dialogCallback=null,editContext=null;
function ask(title,message,callback,yes='Продолжить'){dialogCallback=callback;openDialog(title,`<p class="small muted">${message}</p>`,button(yes,'dialog-confirm','primary'))}
function entityDialog(kind,id,fromDoc=false){const r=(db[kind]||[]).find(r=>r.id===id)||{};editContext={kind,id,fromDoc};let body='';if(kind==='items'){body=`<form id="entity-form" class="form-grid two">${labeled('Наименование','name',r.name||'','text',true)}${labeled('Код','id',r.id||'','text',false,r.id?'readonly':'placeholder="Автоматически"')}<label class="field">Тип<select name="type"><option ${r.type==='Товар'?'selected':''}>Товар</option><option ${r.type==='Услуга'?'selected':''}>Услуга</option></select></label>${labeled('Единица измерения','unit',r.unit||'шт.','text',true)}${labeled('Цена продажи, ₽','price',r.price||0,'number',true,'min="0" step=".01"')}${labeled('Учётная стоимость, ₽','cost',r.cost||0,'number',true,'min="0" step=".01"')}${labeled('Минимальный остаток','min',r.min||0,'number',false,'min="0"')}</form>`}else{body=`<form id="entity-form" class="form-grid two">${labeled('Наименование','name',r.name||'','text',true)}${labeled('Контактное лицо','contact',r.contact||'')}${labeled('Телефон','phone',r.phone||'')}${labeled('Электронная почта','email',r.email||'','email')}${labeled('Город','city',r.city||'')}${labeled('ИНН','inn',r.inn||'')}<label class="field wide">Адрес<input name="address" value="${esc(r.address||'')}"></label></form>`}openDialog((id?'Изменить: ':'Добавить: ')+(kind==='items'?'номенклатура':kind==='suppliers'?'поставщик':'клиент'),body,button('Сохранить','save-entity','primary'))}
function saveEntity(){const f=$('#entity-form');if(!f.reportValidity())return;const obj=Object.fromEntries(new FormData(f)),{kind,id,fromDoc}=editContext;obj.name=obj.name.trim();if(!obj.name){toast('Укажите наименование',true);return}if(kind==='items'){for(const k of ['price','cost','min'])obj[k]=+obj[k]||0;obj.id=obj.id.trim()||'ITEM-'+String(db.items.length+1).padStart(4,'0');if(!id&&db.items.some(i=>i.id===obj.id)){toast('Такой код уже существует',true);return}}else obj.id=id||uid(kind==='customers'?'C':'S');const current=db[kind].find(r=>r.id===id);if(kind==='items'&&current&&current.type!==obj.type&&(current.qty||current.reserved)){toast('Сначала завершите движения и обнулите остатки этой позиции',true);return}if(current)Object.assign(current,obj);else db[kind].push({...obj,qty:0,reserved:0});persist();$('#dialog').close();if(fromDoc&&draft){draft.partner=obj.id;dirty=true;renderDocument()}else render();toast('Карточка сохранена')}
function paymentDialog(source,refund=false){const d=source||draft;let chosen=d?(route.page==='invoices'?d.source||d.id:d.id):'';if(d?.state==='draft'){toast('Сначала подтвердите документ',true);return}const options=[...db.orders.filter(o=>o.state!=='draft'),...db.invoices.filter(o=>!o.source&&o.state==='submitted')];let list=options.map(o=>`<option value="${o.id}" ${o.id===chosen?'selected':''}>${o.id} · ${esc(partner(o)?.name)} · ${refund?'оплачено '+money(paid(o)):'к оплате '+money(due(o))}</option>`).join('');openDialog(refund?'Возврат оплаты':'Принять оплату',`<form id="payment-form" class="form-grid two"><label class="field wide">Заказ клиента <span class="required">*</span><select name="source" required>${list}</select></label>${labeled('Сумма, ₽','amount',d?(refund?paid(d,route.page):due(d,route.page))||'':'','number',true,'min=".01" step=".01"')}${labeled('Дата','date',DEMO_DATE,'date',true)}<label class="field">Счёт<select name="account"><option>Расчётный счёт</option><option>Касса</option></select></label>${labeled('Назначение','purpose',refund?'Возврат оплаты':'Оплата по заказу')}<input name="direction" type="hidden" value="${refund?'out':'in'}"></form>`,button(refund?'Сохранить возврат':'Сохранить оплату','save-payment','primary'))}
function savePayment(){const f=$('#payment-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f)),o=db.orders.find(o=>o.id===d.source)||db.invoices.find(o=>o.id===d.source&&!o.source);d.amount=+d.amount;if(!o||!Number.isFinite(d.amount)||d.amount<=0){toast('Проверьте заказ и сумму оплаты',true);return}if(d.direction==='out'&&d.amount>paid(o)){toast('Возврат превышает полученную оплату',true);return}if(d.direction==='in'&&d.amount>due(o)){toast('Сумма превышает неоплаченный остаток '+money(due(o)),true);return}d.id='PAY-2026-'+String(Math.max(0,...db.payments.map(p=>+p.id.split('-').pop()||0))+1).padStart(4,'0');d.partner=o.partner;d.state='submitted';db.payments.unshift(d);o.history.push({text:(d.direction==='out'?'Возвращена оплата: ':'Получена оплата: ')+money(d.amount),at:d.date+'T12:00:00'});persist();$('#dialog').close();if(draft){draft=structuredClone(db[route.page]?.find(x=>x.id===draft.id)||draft)}render();toast(d.direction==='out'?'Возврат сохранён':'Оплата сохранена')}
function expenseDialog(){openDialog('Добавить расход',`<form id="expense-form" class="form-grid two">${labeled('Сумма, ₽','amount','','number',true,'min=".01" step=".01"')}${labeled('Дата','date',DEMO_DATE,'date',true)}<label class="field">Статья<select name="category"><option>Аренда</option><option>Связь</option><option>Доставка</option><option>Материалы</option><option>Прочие расходы</option></select></label><label class="field">Счёт<select name="account"><option>Расчётный счёт</option><option>Касса</option></select></label><label class="field wide">Назначение <span class="required">*</span><input name="purpose" required placeholder="На что потрачены деньги"></label></form>`,button('Сохранить расход','save-expense','primary'))}
function saveExpense(){const f=$('#expense-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.amount=+d.amount;d.id='EXP-2026-'+String(Math.max(0,...db.expenses.map(p=>+p.id.split('-').pop()||0))+1).padStart(4,'0');d.state='submitted';db.expenses.unshift(d);persist();$('#dialog').close();render();toast('Расход сохранён')}
function stockDialog(){openDialog('Движение товаров',`<form id="stock-form" class="form-grid two"><label class="field">Операция<select name="operation"><option>Списание</option><option>Оприходование</option></select></label>${labeled('Дата','date',DEMO_DATE,'date',true)}<label class="field wide">Номенклатура <span class="required">*</span><select name="item" required>${db.items.filter(i=>i.type==='Товар').map(i=>`<option value="${i.id}">${esc(i.name)} · доступно ${i.qty-i.reserved}</option>`).join('')}</select></label>${labeled('Количество','qty',1,'number',true,'min=".001" step="any"')}<label class="field">Склад<input name="warehouse" value="Основной склад" readonly></label><label class="field wide">Комментарий<input name="notes" placeholder="Причина операции"></label></form>`,button('Подтвердить','save-stock-operation','primary'))}
function saveStockOperation(){const f=$('#stock-form');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f)),it=item(v.item),qty=+v.qty;if(!it||!Number.isFinite(qty)||qty<=0)return;if(v.operation==='Списание'&&qty>it.qty-it.reserved){toast('Для списания доступно '+(it.qty-it.reserved)+' '+it.unit,true);return}const delta=v.operation==='Списание'?-qty:qty;it.qty+=delta;const d={id:nextId('stockDocs'),operation:v.operation,date:v.date,warehouse:v.warehouse,state:'submitted',lines:[{item:it.id,qty:delta}],notes:v.notes};db.stockDocs.unshift(d);persist();$('#dialog').close();render();toast('Движение товаров зарегистрировано')}
function saveInventory(){const entries=$$('[data-inventory]');if(entries.some(el=>!el.checkValidity()||!Number.isFinite(+el.value))){toast('Проверьте фактические остатки и резервы',true);return}const changes=entries.map(el=>({item:el.dataset.inventory,qty:+el.value-item(el.dataset.inventory).qty})).filter(l=>l.qty!==0);if(!changes.length){toast('Расхождений нет: остатки совпадают');return}changes.forEach(l=>item(l.item).qty+=l.qty);const d={id:nextId('stockDocs'),operation:'Инвентаризация',date:$('.settings-content input[name="date"]')?.value||DEMO_DATE,warehouse:'Основной склад',state:'submitted',lines:changes,notes:$('#inventory-note')?.value||''};db.stockDocs.unshift(d);persist();render();toast('Остатки обновлены, документ '+d.id+' сохранён')}
function advancedFilters(){openDialog('Фильтры списка',`<div class="form-grid two"><label class="field">Поиск<input id="advanced-search" value="${esc(listState.search)}" placeholder="Название или номер"></label><label class="field">Порядок сортировки<select id="advanced-direction"><option value="-1" ${listState.dir===-1?'selected':''}>По убыванию</option><option value="1" ${listState.dir===1?'selected':''}>По возрастанию</option></select></label></div><p class="small muted">Фильтры действуют совместно с выбранным статусом.</p>`,button('Сбросить','reset-filters','outline')+button('Применить','apply-filters','primary'))}
function columnDialog(){const all=listColumns[route.page]||listColumns.docs,s=columnsFor(route.page).map(([k])=>k);openDialog('Колонки списка',`<div class="column-list">${all.map(([key,title])=>`<label><input type="checkbox" name="column" value="${key}" ${s.includes(key)?'checked':''}>${title}</label>`).join('')}</div>`,button('По умолчанию','reset-columns','outline')+button('Сохранить','save-columns','primary'))}
function exportFile(text,name,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvValue(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s)&&!Number.isFinite(Number(s)))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
function downloadCsv(heads,rows,name){exportFile('\ufeff'+[heads,...rows].map(r=>r.map(csvValue).join(';')).join('\r\n'),name,'text/csv;charset=utf-8')}
function rawCell(d,key,kind){switch(key){case 'partner':return partner(d,kind)?.name||'';case 'sum':return calc(d);case 'paid':return paid(d,kind);case 'debt':return due(d,kind);case 'status':return status(d,kind).text;case 'valuation':return d.qty*d.cost;case 'available':return d.qty-d.reserved;case 'billed':return billedPct(d);case 'warehouse':return d.warehouse||'Основной склад';case 'party':return db.customers.find(c=>c.id===d.partner)?.name||d.partner;case 'stockStatus':return d.qty<d.min?'Пополнить':'В наличии';case 'syncStatus':return d.state;case 'clientDebt':return db.orders.filter(o=>o.partner===d.id).reduce((a,o)=>a+due(o),0);case 'supplierDebt':return db.purchaseOrders.filter(o=>o.partner===d.id).reduce((a,o)=>a+due(o,'purchaseOrders'),0);default:return d[key]||''}}
function exportList(onlySelected=false,forceKind){const k=forceKind||route.page,cols=columnsFor(k),data=forceKind?db[k]:listData().filter(d=>!onlySelected||selected.has(d.id));downloadCsv(cols.map(c=>c[1]),data.map(d=>cols.map(([key])=>rawCell(d,key,k))),'erpbasic-'+k+'.csv');toast('Выгрузка подготовлена')}
function parseCsv(s){s=s.replace(/^\ufeff/,'');const delimiter=s.split('\n')[0].includes(';')?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
let importMode='items',importPrepared=null;
function importDialog(mode){importMode=mode;importPrepared=null;const bank=mode==='bank';openDialog(bank?'Импорт банковской выписки':'Импорт номенклатуры',`<p class="small muted">CSV в кодировке UTF-8, разделитель «;».</p><div class="info-box">${bank?'Дата;Заказ;Сумма;Счёт;Назначение':'Код;Наименование;Тип;Единица;Цена;Стоимость'}</div><input id="import-file" type="file" accept=".csv,text/csv" class="csv-input" aria-label="CSV файл"><div id="import-preview" class="small muted erp-mt-17">Выберите файл для проверки. Данные будут добавлены после подтверждения.</div>`,button('Скачать шаблон','import-template','outline','download')+button('Импортировать','confirm-import','primary'))}
async function inspectImport(file){if(!file)return;try{const rows=parseCsv(await file.text());if(rows.length<2)throw new Error('В файле нет строк данных.');const expected=importMode==='bank'?5:6;if(rows[0].length<expected)throw new Error('Не хватает колонок. Используйте шаблон.');const data=rows.slice(1).map((r,i)=>{if(r.length<expected)throw new Error('Строка '+(i+2)+': недостаточно колонок.');if(importMode==='bank'){let [date,source,amount,account,purpose]=r;amount=Number(amount.replace(',','.'));const o=db.orders.find(o=>o.id===source.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!o||!Number.isFinite(amount)||amount<=0)throw new Error('Строка '+(i+2)+': проверьте дату, номер заказа и положительную сумму.');return {date,source:o.id,amount,account:account||'Расчётный счёт',purpose:purpose||'Импорт выписки',partner:o.partner}}let [id,name,type,unit,price,cost]=r;price=Number(price.replace(',','.'));cost=Number(cost.replace(',','.'));if(!id.trim()||!name.trim()||!['Товар','Услуга'].includes(type)||!Number.isFinite(price)||price<0||!Number.isFinite(cost)||cost<0)throw new Error('Строка '+(i+2)+': проверьте код, название, тип и цены.');return {id:id.trim(),name:name.trim(),type,unit:unit||'шт.',price,cost,qty:0,reserved:0,min:0}});if(importMode==='bank'){const sums={};data.forEach(p=>sums[p.source]=(sums[p.source]||0)+p.amount);for(const [source,sum] of Object.entries(sums)){const o=db.orders.find(o=>o.id===source);if(sum>due(o))throw new Error('Сумма по '+source+' превышает неоплаченный остаток.')}}importPrepared=data;$('#import-preview').textContent='Проверено: '+data.length+' строк. '+(importMode==='items'?'Существующие коды будут обновлены.':'Платежи будут связаны с заказами.')}catch(e){importPrepared=null;$('#import-preview').textContent=e.message;$('#import-preview').className='error'}}
function confirmImport(){if(!importPrepared){toast('Сначала выберите и проверьте CSV файл',true);return}let added=0;if(importMode==='items'){for(const r of importPrepared){const current=item(r.id);if(current){const {qty,reserved,min,...fields}=r;Object.assign(current,fields)}else db.items.push(r);added++}}else{for(const r of importPrepared){if(db.payments.some(p=>p.source===r.source&&p.date===r.date&&p.amount===r.amount&&p.purpose===r.purpose))continue;db.payments.push({...r,id:'PAY-2026-'+String(Math.max(0,...db.payments.map(p=>+p.id.split('-').pop()||0))+1).padStart(4,'0'),direction:'in',state:'submitted'});added++}}persist();$('#dialog').close();render();toast('Импортировано: '+added+' строк')}
function showSearch(){const el=$('#dialog');el.innerHTML=`<div class="search-dialog"><input id="global-search" placeholder="Поиск документов, клиентов и команд…" aria-label="Поиск по системе" autocomplete="off"></div><div id="search-results" class="search-results"></div><div class="dialog-foot"><span class="small muted erp-push-left">Ctrl K — открыть · Esc — закрыть</span>${button('Закрыть','close-dialog')}</div>`;if(!el.open)el.showModal();renderSearch('');$('#global-search').focus()}
function renderSearch(q){q=q.toLowerCase().trim();let entries=[];for(const [module,m] of Object.entries(modules))for(const [p,n,ic] of m.links)if(!q||[n,m.name].join(' ').toLowerCase().includes(q))entries.push({title:n,sub:m.name,href:link(module,p),icon:ic});for(const k of ['orders','invoices','purchaseOrders'])for(const d of db[k]){const p=partner(d,k)?.name||'';if(q&&[p,d.id].join(' ').toLowerCase().includes(q))entries.push({title:p,sub:kindMeta[k].singular+' · '+d.id,href:link(kindMeta[k].module,k,d.id),icon:'paper'})}for(const p of db.customers)if(q&&p.name.toLowerCase().includes(q))entries.push({title:p.name,sub:'Клиент',action:'search-customer',id:p.id,icon:'users'});$('#search-results').innerHTML=`<div class="search-category">${q?'Результаты поиска':'Перейти в раздел'}</div>`+entries.slice(0,20).map(e=>`<a class="search-result" ${e.href?`href="${e.href}" data-action="search-navigate"`:`href="#" data-action="${e.action}" data-id="${e.id}"`}>${icon(e.icon)}<span>${esc(e.title)}<small>${esc(e.sub)}</small></span>${icon('arrow')}</a>`).join('')+(!entries.length?'<div class="empty">Ничего не найдено</div>':'')}
function showHelp(){openDialog('ERPbasic · рабочий прототип',`<div class="help-grid"><p>Интерфейс использует компоновку ERPNext: модули, рабочие пространства, списки и документы.</p><p><strong>Можно проверить:</strong> создание и подтверждение заказа, реализацию, частичную оплату, возврат, закупку и поступление, инвентаризацию, справочники и отчёты.</p><p><strong>Сохранение:</strong> данные остаются в браузере на этом устройстве. Резервную копию можно скачать в настройках.</p><p><strong>Рабочий запуск:</strong> учётное ядро ERPNext, серверная база, права доступа и интеграция Clientora пока не подключены.</p><p class="muted">Ctrl K — поиск · Esc — закрыть окно.</p></div>`,button('Настройки данных','open-data','outline','download'))}
function notifications(){openDialog('Требует внимания',`<div class="card-list"><a class="connection-card" href="${link('sales','orders')}" data-action="search-navigate"><span>Открытые заказы<small>${db.orders.filter(o=>status(o).key==='open').length} ожидают выполнения</small></span>${icon('arrow')}</a><a class="connection-card" href="${link('stock','balances')}" data-action="search-navigate"><span>Остатки ниже минимума<small>${db.items.filter(i=>i.type==='Товар'&&i.qty<i.min).length} позиций</small></span>${icon('arrow')}</a><a class="connection-card" href="${link('sync','queue')}" data-action="search-navigate"><span>Операции обмена<small>${db.sync.filter(s=>s.state==='waiting').length} ожидают передачи</small></span>${icon('arrow')}</a></div>`)}
function bindPage(){if($('#list-search'))$('#list-search').addEventListener('input',e=>{listState.search=e.target.value;listState.page=1;updateList()});if($('#list-status'))$('#list-status').addEventListener('change',e=>{listState.status=e.target.value;listState.page=1;selected.clear();updateList()});if($('#only-low'))$('#only-low').addEventListener('change',e=>{listState.onlyLow=e.target.checked;updateList()});if($('#list-view'))$('#list-view').addEventListener('change',e=>{listState.view=e.target.value;updateList()});if($('#report-select'))$('#report-select').addEventListener('change',e=>{location.hash=link(route.module,'reports',e.target.value)})}
function handleAction(action,el,event){const id=el.dataset.id;switch(action){
case 'sidebar-toggle':showSidebar=!showSidebar;$('.sidebar')?.classList.toggle('open',showSidebar);$('.mobile-overlay')?.classList.toggle('visible',showSidebar);break;
case 'close-dialog':$('#dialog').close();break;
case 'dialog-confirm':{const fn=dialogCallback;dialogCallback=null;$('#dialog').close();fn?.();break}
case 'toggle-theme':setTheme(activeTheme()==='dark'?'light':'dark');break;case 'set-theme':setTheme(id);break;case 'search':showSearch();break;case 'help':showHelp();break;case 'notifications':notifications();break;
case 'user-menu':openDialog('Алексей Курносов',`<p class="small muted">Владелец · ${esc(db.company)}</p>${themePicker()}<div class="help-grid"><a class="btn outline" href="${link('settings','home')}" data-action="search-navigate">${icon('settings')}Настройки компании</a><a class="btn outline" href="${link('settings','data')}" data-action="search-navigate">${icon('download')}Данные и резервная копия</a></div>`);break;
case 'search-navigate':$('#dialog').close();break;
case 'search-customer':entityDialog('customers',id);break;
case 'open-data':$('#dialog').close();navigate('settings','data');break;
case 'workspace-settings':navigate('settings','profile');break;
case 'dismiss-onboarding':db.onboardingDismissed=true;persist();render();break;
case 'open-orders':navigate('sales','orders');break;case 'open-sales-reports':navigate('sales','reports');break;
case 'low-stock':listState.onlyLow=true;if(route.module==='stock'&&route.page==='balances')render();else{location.hash=link('stock','balances');setTimeout(()=>{listState.onlyLow=true;render()},0)}break;
case 'new-document':{const k=route.page;if(k==='items')entityDialog('items');else if(k==='customers'||k==='suppliers')entityDialog(k);else if(k==='payments')paymentDialog();else if(k==='expenses')expenseDialog();else newDoc(kindMeta[k]?.prefix?k:route.module==='buying'?'purchaseOrders':'orders');break}
case 'edit-record':entityDialog(route.page,id);break;case 'edit-item':entityDialog('items',id);break;case 'save-entity':saveEntity();break;
case 'add-doc-partner':captureDraft();entityDialog(kindMeta[route.page].partner,null,true);break;
case 'edit-doc-partner':entityDialog(kindMeta[route.page].partner,draft.partner,true);break;
case 'list-menu':currentMenu=currentMenu==='list'?'':'list';renderList();break;
case 'doc-menu':captureDraft();currentMenu=currentMenu==='doc'?'':'doc';renderDocument();break;
case 'create-menu':currentMenu=currentMenu==='create'?'':'create';renderDocument();break;
case 'refresh':if(route.id){renderDocument()}else{renderList()}toast('Список обновлён');break;
case 'columns':columnDialog();break;
case 'save-columns':{const cols=$$('#dialog input[name=column]:checked').map(c=>c.value);if(!cols.length){toast('Выберите хотя бы одну колонку',true);return}db.views[route.page]={columns:cols};persist();$('#dialog').close();renderList();break}
case 'reset-columns':delete db.views[route.page];persist();$('#dialog').close();renderList();break;
case 'advanced-filters':advancedFilters();break;
case 'apply-filters':listState.search=$('#advanced-search').value;listState.dir=+$('#advanced-direction').value;listState.page=1;$('#dialog').close();renderList();break;
case 'reset-filters':listState.search='';listState.status='all';listState.onlyLow=false;listState.page=1;$('#dialog').close();renderList();break;
case 'sort':listState.dir*=-1;updateList();break;
case 'column-sort':if(listState.sort===id)listState.dir*=-1;else{listState.sort=id;listState.dir=1}updateList();break;
case 'select-row':if(el.checked)selected.add(id);else selected.delete(id);updateList();break;
case 'select-all':{const data=listData().slice((listState.page-1)*listState.limit,listState.page*listState.limit);for(const d of data)el.checked?selected.add(d.id):selected.delete(d.id);updateList();break}
case 'clear-selection':selected.clear();updateList();break;
case 'page-size':listState.limit=+id;listState.page=1;updateList();break;case 'prev-page':listState.page--;updateList();break;case 'next-page':listState.page++;updateList();break;
case 'favorite':db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[...db.favorites,id];persist();renderList();break;
case 'export-list':exportList();currentMenu='';break;case 'export-selected':exportList(true);break;case 'export-orders':exportList(false,'orders');break;
case 'print':window.print();break;
case 'doc-tab':captureDraft();docTab=id;currentMenu='';renderDocument();break;
case 'add-line':captureDraft();draft.lines.push({item:'',qty:1,rate:0});markDirty();$('#doc-lines').innerHTML=renderDocLines(false);break;
case 'remove-line':captureDraft();draft.lines.splice(+id,1);markDirty();$('#doc-lines').innerHTML=renderDocLines(false);updateDocTotals();break;
case 'save-document':saveDocument();break;case 'submit-document':saveDocument(true);break;case 'saved':toast('Документ уже сохранён и подтверждён');break;
case 'back-to-list':navigate(route.module,route.page);break;
case 'duplicate-document':{captureDraft();const source=structuredClone(draft);dirty=false;source.source=null;newDoc(route.page);pendingNew={...source,id:nextId(route.page),kind:route.page,state:'draft',paid:0,delivered:0,source:null,history:[],date:DEMO_DATE};if(route.id==='new'){draft=pendingNew;pendingNew=null;renderDocument()}currentMenu='';break}
case 'amend-document':{if(['receipts','invoices'].includes(route.page)){toast('Подтверждённое движение сохраняется. Для новой операции создайте отдельный документ.',true);return}if(connectionCount(draft)){toast('У документа есть связанные операции. Создайте новый заказ или копию.',true);return}draft.state='draft';dirty=true;currentMenu='';renderDocument();break}
case 'create-invoice':{const existing=db.invoices.find(i=>i.source===draft.id);currentMenu='';if(existing){navigate('sales','invoices',existing.id);toast('Открыта связанная реализация')}else newDoc('invoices',draft);break}
case 'create-receipt':{const existing=db.receipts.find(i=>i.source===draft.id);currentMenu='';if(existing){navigate('buying','receipts',existing.id);toast('Открыто связанное поступление')}else newDoc('receipts',draft);break}
case 'convert-order':{if(draft.converted){navigate('sales','orders',draft.converted);return}const source=structuredClone(draft);newDoc('orders',source);break}
case 'purchase-from-order':{const source=structuredClone(draft);source.partner='';source.lines=source.lines.filter(l=>item(l.item)?.type==='Товар').map(l=>({...l,rate:item(l.item)?.cost||0}));if(!source.lines.length){toast('В заказе нет товаров для закупки');return}newDoc('purchaseOrders',source);break}
case 'receive-payment':paymentDialog(draft);break;case 'refund-payment':paymentDialog(null,true);break;case 'save-payment':savePayment();break;
case 'save-expense':saveExpense();break;
case 'comment':{const t=$('#comment-text').value.trim();if(!t)return;draft.history.push({text:t,at:DEMO_DATE+'T12:00:00'});const d=db[route.page].find(x=>x.id===draft.id);if(d)d.history=structuredClone(draft.history);persist();renderDocument();toast('Комментарий добавлен');break}
case 'doc-tags':openDialog('Метки документа',labeled('Метки через запятую','tags',draft.tags||''),button('Сохранить','save-tags','primary'));break;
case 'save-tags':draft.tags=$('#dialog input[name=tags]').value;{const d=db[route.page].find(x=>x.id===draft.id);if(d)d.tags=draft.tags;persist();$('#dialog').close();renderDocument()}break;
case 'attachments':openDialog('Вложения',`<p class="small muted">Документ ${esc(draft.id)}</p><p class="small muted">Хранение и обмен файлами будут доступны после подключения серверной базы. Сейчас можно добавить ссылку в комментарий к документу.</p>`);break;
case 'export-document':exportFile(JSON.stringify(draft,null,2),draft.id+'.json','application/json');break;
case 'stock-operation':stockDialog();break;case 'save-stock-operation':saveStockOperation();break;case 'save-inventory':saveInventory();break;
case 'apply-report':{if($('#report-start').value>$('#report-end').value){toast('Дата начала должна быть раньше даты окончания',true);return}reportRange={start:$('#report-start').value,end:$('#report-end').value};renderReport();break}
case 'export-report':downloadCsv(reportHeads,reportRows,'erpbasic-report.csv');break;
case 'save-company':{const f=$('#company-form');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));db.company=d.company.trim();db.city=d.city;persist();renderSettings();toast('Настройки компании сохранены');break}
case 'save-profile':db.profile=$('#profile-select').value;db.items.sort((a,b)=>{const t=db.profile==='Услуги'?'Услуга':'Товар';return (b.type===t)-(a.type===t)});persist();renderSettings();toast('Профиль «'+db.profile+'» сохранён');break;
case 'backup':exportFile(JSON.stringify(db,null,2),'erpbasic-backup-v2.json','application/json');if($('#upgrade-backup'))$('#upgrade-backup').checked=true;toast('Резервная копия подготовлена');break;
case 'restore':restorePrepared=null;openDialog('Восстановить данные',`<p class="small muted">Выберите ранее скачанную копию ERPbasic v2. Текущие данные будут заменены.</p><input type="file" id="restore-file" accept=".json,application/json" aria-label="Резервная копия"><div id="restore-preview" class="small muted erp-mt-15"></div>`,button('Восстановить','restore-confirm','primary'));break;
case 'restore-confirm':{if(!restorePrepared){toast('Выберите корректную резервную копию',true);return}const copy=restorePrepared;ask('Заменить данные прототипа?','Текущие данные можно сохранить, закрыв это окно и скачав резервную копию.',()=>{db=copy;persist();draft=null;dirty=false;render();toast('Данные восстановлены')},'Заменить данные');break}
case 'import-data':case 'import-items':importDialog('items');break;case 'import-bank':importDialog('bank');break;
case 'import-template':downloadCsv(importMode==='bank'?['Дата','Заказ','Сумма','Счёт','Назначение']:['Код','Наименование','Тип','Единица','Цена','Стоимость'],importMode==='bank'?[[DEMO_DATE,db.orders.find(o=>due(o)>0)?.id||'SO-2026-0048',1000,'Расчётный счёт','Оплата по заказу']]:[['NEW-001','Новая позиция','Товар','шт.',1200,800]],'erpbasic-'+importMode+'-template.csv');break;
case 'confirm-import':confirmImport();break;
case 'retry-sync':db.sync.forEach(s=>{s.state='done';s.updated='05.11.2026, 12:00'});persist();renderSync();toast('Демонстрационная очередь обработана');break;
case 'retry-one':{const s=db.sync.find(s=>s.id===id);if(s){s.state='done';s.updated='05.11.2026, 12:00';persist();renderList();toast('Демонстрационная операция обработана')}break}
case 'upgrade-check':{const errors=[];if(db.orders.some(o=>!o.partner||!o.lines.length))errors.push('Проверьте заполнение заказов');openDialog('Подготовка перехода',`<div class="help-grid"><p>${icon('check')} Документы: ${db.orders.length} заказов, ${db.invoices.length} реализаций</p><p>${icon('check')} Справочники: ${db.customers.length} клиентов, ${db.items.length} позиций</p><p>${icon('check')} Заказы к оплате: ${money(db.orders.filter(o=>o.state!=='draft').reduce((a,o)=>a+due(o),0))}</p><p>${icon('check')} Стоимость запасов: ${money(db.items.filter(i=>i.type==='Товар').reduce((a,i)=>a+i.qty*i.cost,0))}</p>${errors.map(t=>`<p class="error">${t}</p>`).join('')}<div class="info-box">Следующий этап — проверка копии в ERPNext и настройка новых процессов. В прототипе сохраняется контрольная копия данных.</div></div>`,button('Скачать контрольную копию','backup','primary','download'));break}
}}
function updateDocTotals(){if($('#subtotal'))$('#subtotal').textContent=money(draft.lines.reduce((a,l)=>a+l.qty*l.rate,0));if($('#grand-total'))$('#grand-total').textContent=money(calc(draft))}
let restorePrepared=null;
document.addEventListener('click',e=>{const actionEl=e.target.closest('[data-action]'),anchor=e.target.closest('a[href^="#/"]');if(anchor&&dirty&&!actionEl?.matches('[data-action="search-navigate"]')){e.preventDefault();const hash=anchor.getAttribute('href');ask('Несохранённые изменения','Изменения документа ещё не сохранены.',()=>{dirty=false;location.hash=hash},'Выйти без сохранения');return}if(actionEl){if(actionEl.tagName==='BUTTON'||actionEl.getAttribute('href')==='#')e.preventDefault();handleAction(actionEl.dataset.action,actionEl,e);return}const row=e.target.closest('[data-open]');if(row&&!e.target.closest('a,input,button,select'))navigate(route.module,route.page,row.dataset.open)});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='global-search'){renderSearch(t.value);return}if(t.dataset.line!==undefined&&draft){const l=draft.lines[+t.dataset.line],key=t.dataset.field;if(key==='qty'||key==='rate'){l[key]=Number(t.value);markDirty();const out=$('#line-amount-'+t.dataset.line);if(out)out.textContent=money(l.qty*l.rate);updateDocTotals()}return}if(t.closest('#document-form')||t.id==='doc-terms'){captureDraft();markDirty();updateDocTotals()}if(t.dataset.inventory){const difference=Number(t.value)-item(t.dataset.inventory).qty;$('#diff-'+t.dataset.inventory).textContent=(difference>0?'+':'')+difference}});
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.field==='item'&&draft){captureDraft();const l=draft.lines[+t.dataset.line],it=item(t.value);l.item=t.value;l.rate=(route.page==='purchaseOrders'||route.page==='receipts'?it?.cost:it?.price)||0;markDirty();$('#doc-lines').innerHTML=renderDocLines(false);updateDocTotals()}else if(t.closest('#document-form')){captureDraft();markDirty()}if(t.id==='import-file')await inspectImport(t.files[0]);if(t.id==='restore-file'){restorePrepared=null;try{const obj=JSON.parse(await t.files[0].text());if(obj.schema!==2||typeof obj.company!=='string'||!['orders','items','customers','suppliers','payments','invoices','quotes','purchaseOrders','receipts','stockDocs','expenses','sync','favorites'].every(k=>Array.isArray(obj[k]))||!obj.settings||!obj.views||obj.orders.some(o=>!o.id||!Array.isArray(o.lines)))throw new Error('Формат резервной копии не поддерживается');restorePrepared=obj;$('#restore-preview').textContent='Копия проверена: '+obj.company+', заказов — '+obj.orders.length}catch(err){$('#restore-preview').textContent='Не удалось прочитать копию: '+err.message}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&draft){e.preventDefault();saveDocument()}if(e.key==='Enter'&&e.target.id==='scan-item'){e.preventDefault();const it=db.items.find(i=>i.id.toLowerCase()===e.target.value.trim().toLowerCase());if(it){captureDraft();const empty=draft.lines.find(l=>!l.item);if(empty){empty.item=it.id;empty.rate=it.price}else draft.lines.push({item:it.id,qty:1,rate:it.price});markDirty();$('#doc-lines').innerHTML=renderDocLines(false);updateDocTotals();e.target.value='';toast('Позиция добавлена')}else toast('Позиция с таким кодом не найдена',true)}});
document.addEventListener('submit',e=>e.preventDefault());
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('hashchange',routeChanged);
const originalRenderDocument=renderDocument;renderDocument=function(){if(route.page==='stockDocs'){renderStockDocument();return}originalRenderDocument()};
routeChanged();
function renderDashboard(){const arr=db.orders.filter(o=>o.state!=='draft'),sum=arr.reduce((a,o)=>a+calc(o),0),income=db.payments.reduce((a,p)=>a+(p.direction==='out'?-p.amount:p.amount),0);renderShell(`<div class="home-content"><div class="home-intro"><div><p class="eyebrow">${esc(db.company)}</p><h1>Показатели продаж</h1><span class="muted small">Ноябрь 2026 · управленческий обзор</span></div></div><div class="cards">${metric('Подтверждённые заказы',money(sum),arr.length+' документов',link('sales','orders'))}${metric('Получено оплат',money(income),'С учётом возвратов',link('finance','payments'))}${metric('Осталось оплатить',money(arr.reduce((a,o)=>a+due(o),0)),'По заказам клиентов',link('finance','receivables'))}</div><div class="erp-mt-22">${trendChart('sales')}</div><div class="cards">${workspaceCard('Продажи',[['Продажи по заказам','reports'],['Валовая прибыль','reports/profit']])}${workspaceCard('Выполнение',[['Заказы клиентов','orders'],['Реализации','invoices']])}${workspaceCard('Деньги',[['Долги клиентов','receivables','finance'],['Оплаты','payments','finance']])}</div><div class="recent"><div class="card-title">Последние заказы</div>${miniOrders(db.orders.slice(0,5))}</div></div>`,button('Открыть отчёты','open-sales-reports','','arrow'),'<strong>Показатели</strong>')}
